import 'dart:typed_data';
import 'dart:ui' as ui;
import 'dart:ui';
import 'package:flutter/material.dart';
import 'package:vector_math/vector_math_64.dart' hide Colors;
import 'dart:math' as math;

class SpherePainter extends CustomPainter {
  final ui.Image texture;
  BuildContext context;

  Vector3 position = Vector3.zero();
  final Vector3 scale = Vector3(1, 1, 1);
  Vector3 rotation = Vector3.zero();

  Quaternion rotationQuat = Quaternion.identity();

  // Geometria da esfera
  static List<Vector3> staticVertices = [];
  static List<Offset> staticTexcoords = [];
  static List<List<int>> staticIndices = [];
  static bool isSphereGenerated = false;

  final Matrix4 transform = Matrix4.identity();
  final double radius = 3.12;
  final int latSegments = 10; // Ajustado para melhor performance
  final int lonSegments = 10;

  SpherePainter(this.texture, this.position, this.context) {
    if (!isSphereGenerated) {
      _generateSphere();
      isSphereGenerated = true;
    }
  }

  void _generateSphere() {
    for (int y = 0; y <= latSegments; ++y) {
      final double v = y / latSegments;
      final double sv = math.sin(v * math.pi);
      final double cv = math.cos(v * math.pi);
      for (int x = 0; x <= lonSegments; ++x) {
        final double u = x / lonSegments;
        staticVertices.add(Vector3(
          radius * math.cos(u * math.pi * 2.0) * sv, // X
          radius * cv, // Y
          radius * math.sin(u * math.pi * 2.0) * sv, // Z
        ));
        staticTexcoords.add(Offset(u, v)); // Coordenadas UV normalizadas
      }
    }

    // Preenche os índices dos triângulos com ordem anti-horária consistente
    for (int y = 0; y < latSegments; ++y) {
      for (int x = 0; x < lonSegments; ++x) {
        final int current = (lonSegments + 1) * y + x;
        final int next = current + 1;
        final int below = (lonSegments + 1) * (y + 1) + x;
        final int belowNext = below + 1;

        staticIndices
            .add([current, below, next]); // Triângulo inferior esquerdo
        staticIndices
            .add([next, below, belowNext]); // Triângulo superior direito
      }
    }
  }

  Matrix4 createPerspectiveMatrix(
      double fovY, double aspectRatio, double near, double far) {
    final double f = 1.0 / math.tan(fovY / 2.0);
    return Matrix4(
      f / aspectRatio,
      0,
      0,
      0,
      0,
      f,
      0,
      0,
      0,
      0,
      (far + near) / (near - far),
      -1,
      0,
      0,
      (2 * far * near) / (near - far),
      0,
    );
  }

  void rotate(Vector3 axis, double angleRadians) {
    // Atualiza o quaternion de rotação, mas não aplica a transformação ainda
    Quaternion increment = Quaternion.axisAngle(axis, angleRadians);
    rotationQuat = increment * rotationQuat;
  }

  void updateTransform(BuildContext context) {
    // Parâmetros para a projeção em perspectiva
    double fovY = math.pi / 4; // Campo de visão (45 graus)
    double aspectRatio = 1;
    double near = 1;
    double far = 1000.0;

    // Cria a matriz de projeção perspectiva
    final Matrix4 projection =
        createPerspectiveMatrix(fovY, aspectRatio, near, far);

    // Define a matriz de visualização (view)
    final Matrix4 view = Matrix4.identity()
      ..translate(
          0.0, 0.0, -1001); // Coloque a câmera 5 unidades para trás no eixo Z

    // Atualiza a matriz de modelo com posição, rotação e escala
    final Matrix4 model = Matrix4.compose(position, rotationQuat, scale);

    // Multiplica para obter a matriz MVP final
    final Matrix4 mvp = projection * view * model;

    // Define a transformação final para os vértices
    transform.setFrom(mvp);
  }

/*
  void updateTransform(BuildContext context) {
    // Aplica a transformação baseada na rotação (rotationQuat), posição e escala
    final Matrix4 m = Matrix4.compose(position, rotationQuat, scale);
    transform.setFrom(m);
  }
  */

  Offset convertPositionTo2D(Vector3 position, Matrix4 transform,
      double screenWidth, double screenHeight) {
    position.z = -1000;
    // Aplica a transformação de 3D para 4D (usando w = 1.0)
    Vector4 transformedPosition =
        transform.transformed(Vector4(position.x, position.y, position.z, 1.0));

    // Projeção perspectiva
    double perspective =
        10000.0; // Valor arbitrário para simulação de perspectiva
    double w = perspective / (perspective + transformedPosition.z);

    // Aplica o deslocamento para centralizar no meio da tela
    double x2D = transformedPosition.x * w + screenWidth / 2;
    double y2D = transformedPosition.y * w + screenHeight / 2;

    // Retorna as coordenadas 2D como um Offset
    return Offset(x2D, y2D);
  }

  @override
  void paint(Canvas canvas, Size size) {
    Size size = const Size(330, 603);

    print(convertPositionTo2D(position, transform, 330, 603));
    canvas.drawCircle(convertPositionTo2D(position, transform, 330, 603), 15,
        Paint()..color = Colors.black);

    //rotate(Vector3(math.sin(-rotateAngle), math.cos(rotateAngle), 0), angle);

    updateTransform(context);

    final Float32List positions = Float32List(staticVertices.length * 2);
    final Float32List renderTexcoords = Float32List(staticTexcoords.length * 2);

    // Transformar os vértices
    List<Vector4> transformedVertices =
        List<Vector4>.filled(staticVertices.length, Vector4.zero());
    for (int i = 0; i < staticVertices.length; i++) {
      transformedVertices[i] = transform.transformed(Vector4(
          staticVertices[i].x, staticVertices[i].y, staticVertices[i].z, 1.0));

      // Projeção em perspectiva
      double perspective = 10000.0;
      double w = perspective / (perspective + transformedVertices[i].z);

      // Aplicar o deslocamento para centralizar no meio da tela
      positions[i * 2] = transformedVertices[i].x * w + 330 / 2; // X
      positions[i * 2 + 1] = transformedVertices[i].y * w + 603 / 2; // Y
      /*
        canvas.drawCircle(
            Offset(positions[i * 2] = transformedVertices[i].x * w + 330 / 2,
                positions[i * 2 + 1] = transformedVertices[i].y * w + 603 / 2),
            15,
            Paint()..color = Colors.black);*/

      Offset t = staticTexcoords[i];

      // Corrected texture coordinates to fit the entire texture over the sphere
      double u = t.dx * texture.width; // Map U coordinate by texture width
      double v = t.dy * texture.height; // Map V coordinate by texture height

      renderTexcoords[i * 2] = u; // U
      renderTexcoords[i * 2 + 1] = v; // V
    }

    // Lista para armazenar triângulos visíveis
    List<Triangle> visibleTriangles = [];

    // Calcular e filtrar triângulos com base nas normais (Back-Face Culling)
    for (int i = 0; i < staticIndices.length; i++) {
      final int idx0 = staticIndices[i][0];
      final int idx1 = staticIndices[i][1];
      final int idx2 = staticIndices[i][2];

      Vector4 v0 = transformedVertices[idx0];
      Vector4 v1 = transformedVertices[idx1];
      Vector4 v2 = transformedVertices[idx2];

      // Vetores das arestas do triângulo
      Vector3 edge1 = Vector3(v1.x - v0.x, v1.y - v0.y, v1.z - v0.z);
      Vector3 edge2 = Vector3(v2.x - v0.x, v2.y - v0.y, v2.z - v0.z);

      // Normal do triângulo
      Vector3 normal = edge1.cross(edge2).normalized();

      // Vetor de visão assumindo câmera no eixo Z positivo
      //  Vector3 viewVector = Vector3(0, 0, 1);
      Vector3 viewVector = Vector3(0, 0, -1);

      // Produto escalar entre normal e vetor de visão
      double dotProduct = normal.dot(viewVector);

      // Se o dot product for positivo, o triângulo está voltado para a câmera
      if (dotProduct > 0) {
        // Calcular profundidade média para ordenação
        double depth = (v0.z + v1.z + v2.z) / 3.0;
        visibleTriangles.add(Triangle([idx0, idx1, idx2], depth));
      }
    }

    // Ordenar triângulos do mais distante para o mais próximo
    visibleTriangles.sort((a, b) => b.depth.compareTo(a.depth));

    // Preparar buffers para Vertices.raw
    List<int> renderedIndices = [];
    List<double> renderedPositions = [];
    List<double> renderedTexcoordsList = [];

    // Mapeamento de vértices únicos para evitar duplicações
    Map<int, int> vertexMap = {};
    int currentIndex = 0;

    for (var tri in visibleTriangles) {
      for (int idx in tri.indices) {
        if (!vertexMap.containsKey(idx)) {
          vertexMap[idx] = currentIndex++;
          renderedPositions.add(positions[idx * 2]);
          renderedPositions.add(positions[idx * 2 + 1]);
          renderedTexcoordsList.add(renderTexcoords[idx * 2]);
          renderedTexcoordsList.add(renderTexcoords[idx * 2 + 1]);
        }
        renderedIndices.add(vertexMap[idx]!);
      }
    }

    if (renderedIndices.isEmpty) {
      return; // Nenhum triângulo visível para desenhar
    }

    final Uint16List indexBuffer = Uint16List.fromList(renderedIndices);
    final Float32List positionsBuffer = Float32List.fromList(renderedPositions);
    final Float32List texcoordsBuffer =
        Float32List.fromList(renderedTexcoordsList);

    final verticesData = Vertices.raw(
      VertexMode.triangles,
      positionsBuffer,
      textureCoordinates: texcoordsBuffer,
      indices: indexBuffer,
    );

    final Float64List matrix4 = Matrix4.identity().storage;
    final paint = Paint()
      ..shader = ImageShader(
        texture,
        TileMode.clamp,
        TileMode.clamp,
        matrix4,
      );

    // Desenhar os triângulos visíveis ordenados por profundidade
    canvas.drawVertices(verticesData, BlendMode.dstOver, paint);
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) {
    return true;
  }
}

class Triangle {
  final List<int> indices;
  final double depth;

  Triangle(this.indices, this.depth);
}
